49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        String idempotencyKey = IdempotencyKeys.current();
104	        Owner replayed = IdempotencyKeys.seen(idempotencyKey);
105	        if (replayed != null) {
106	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replayed), HttpStatus.OK);
107	        }
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setHouseholdId(Households.idFor(owner));
111	        Collection<Owner> owners = this.clinicService.findAllOwners().stream()
112	            .filter(o -> !o.getDeleted()).toList();
113	        owner.setRegistrationDate(BusinessDays.effective(owner));
114	        if (owners.stream()
115	            .filter(o -> owner.getRegistrationDate().equals(o.getRegistrationDate())).count() >= 100) {
116	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
117	                "Daily owner-registration limit reached for this date");
118	        }
119	        if (Identities.isDuplicate(owners, owner)) {
120	            throw new ResponseStatusException(HttpStatus.CONFLICT,
121	                "An owner with the same identity already exists");
122	        }
123	        if (CityCodes.countInCity(owners, owner) >= 50) {
124	            throw new ResponseStatusException(HttpStatus.CONFLICT,
125	                "The owner capacity for this city has been reached");
126	        }
127	        owner.setHouseholdMemberCount(Households.size(owners, owner));
128	        owner.setMembershipLevelCap(Households.ceilingLevel(owners, owner));
129	        owner.assignCustomerCode(owners);
130	        owner.setNamesakeCount(Namesakes.count(owners, owner));
131	        owner.setBulkSignupWarning(BulkSignups.exceededDailyLimit(owners, owner));
132	        owner.setCapacityWarning(CityCodes.countInCity(owners, owner) >= 40);
133	        owner.setPossibleDuplicateOf(
134	            PossibleDuplicates.matchId(owners, owner, ownerFieldsDto.getSharesHousehold()));
135	        this.clinicService.saveOwner(owner);
136	        IdempotencyKeys.remember(idempotencyKey, owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
