package org.springframework.samples.petclinic.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Builds an owner's unified memberId as {@code <REGION><FY><HASH8><CHK>}: REGION is the
 * region derived from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
 * otherwise "UNKNOWN"), FY the two-digit registrationDate fiscal year, HASH8 the first 8
 * upper-case hex characters of SHA-256(normalizedTelephone + lastName), and CHK a single
 * Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.
 */
public final class CustomerCode {

    private CustomerCode() {
    }

    /** The memberId for {@code owner} (before any collision suffix). */
    public static String of(Owner owner) {
        String base = region(owner)
            + String.format("%02d", FiscalYear.startYearOf(owner.getRegistrationDate()) % 100)
            + hash8(owner);
        return base + luhn(base);
    }

    /** The region derived from {@code owner}'s postcode, or "UNKNOWN". */
    public static String region(Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode != null && postcode.matches("\\d{4}")) {
            return switch (Integer.parseInt(postcode) / 100) {
                case 20 -> "NSW";
                case 30 -> "VIC";
                case 40 -> "QLD";
                default -> "UNKNOWN";
            };
        }
        return "UNKNOWN";
    }

    private static String hash8(Owner owner) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256")
                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
        return HexFormat.of().withUpperCase().formatHex(digest).substring(0, 8);
    }

    private static int luhn(String s) {
        int sum = 0;
        boolean dbl = true;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

package org.springframework.samples.petclinic.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Locale;

/**
 * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners
 * are the same identity exactly when this key is equal, so a shared surname/postcode with
 * a different telephone yields distinct keys (a soft match, not a hard duplicate).
 */
public final class IdentityKeys {

    private IdentityKeys() {
    }

    /** The identityKey for {@code owner} (64 lower-case hex characters). */
    public static String of(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().strip();
        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
        return sha256Hex(telephone + "|" + email + "|" + soundex(owner.getLastName()));
    }

    /** The American Soundex code of {@code name}, or {@code ""} when it has no letters. */
    public static String soundex(String name) {
        String letters = name == null ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
        if (letters.isEmpty()) {
            return "";
        }
        StringBuilder code = new StringBuilder().append(letters.charAt(0));
        char previous = digitOf(letters.charAt(0));
        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
            char letter = letters.charAt(i);
            char digit = digitOf(letter);
            if (digit != '0' && digit != previous) {
                code.append(digit);
            }
            if (letter != 'H' && letter != 'W') {
                previous = digit;
            }
        }
        while (code.length() < 4) {
            code.append('0');
        }
        return code.toString();
    }

    private static char digitOf(char letter) {
        return switch (letter) {
            case 'B', 'F', 'P', 'V' -> '1';
            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
            case 'D', 'T' -> '3';
            case 'L' -> '4';
            case 'M', 'N' -> '5';
            case 'R' -> '6';
            default -> '0';
        };
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package org.springframework.samples.petclinic.rest.controller.v1;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collection;
import java.util.Locale;
import java.util.OptionalInt;

import org.springframework.samples.petclinic.model.MembershipLevels;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Household-identity rule for owners: two owners share a household when they have the
 * same last name and postcode. The householdId is derived deterministically from that
 * pair, so housemates share it automatically without any explicit link step.
 */
final class Households {

    private Households() {
    }

    /**
     * The deterministic household identifier: the first 12 hex characters of
     * SHA-256 over {@code normalizedLastName + '|' + postcode}.
     */
    static String idFor(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        return sha256Hex12(normalize(owner.getLastName()) + "|" + postcode);
    }

    /**
     * Whether {@code candidate} lands in an existing owner's household and so should be
     * rejected as a duplicate. A {@code sharesHousehold} flag of {@code true} opts out,
     * declaring the candidate a member of that household instead.
     */
    static boolean isDuplicate(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return false;
        }
        return hasHousemate(existing, candidate);
    }

    /** Household size for {@code candidate}: its existing housemates plus itself. */
    static int size(Collection<Owner> existing, Owner candidate) {
        long housemates = existing.stream().filter(other -> sameHousehold(other, candidate)).count();
        return (int) housemates + 1;
    }

    /**
     * The membershipLevel ceiling for {@code candidate}: one above the highest membershipLevel
     * among its existing household members, or {@code null} when it has no household member yet
     * (in which case no cap applies).
     */
    static Integer ceilingLevel(Collection<Owner> existing, Owner candidate) {
        OptionalInt max = existing.stream()
            .filter(other -> sameHousehold(other, candidate))
            .mapToInt(Households::effectiveLevel)
            .max();
        return max.isPresent() ? max.getAsInt() + 1 : null;
    }

    /** An owner's membershipLevel after applying its own ceiling (see {@link #ceilingLevel}). */
    private static int effectiveLevel(Owner owner) {
        int level = MembershipLevels.levelOf(owner);
        Integer cap = owner.getMembershipLevelCap();
        return cap == null ? level : Math.min(level, cap);
    }

    /** Whether an existing owner already belongs to {@code candidate}'s household. */
    static boolean hasHousemate(Collection<Owner> existing, Owner candidate) {
        return existing.stream().anyMatch(other -> sameHousehold(other, candidate));
    }

    private static boolean sameHousehold(Owner a, Owner b) {
        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
    }

    private static String normalize(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String sha256Hex12(String key) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(24);
            for (int i = 0; i < 6; i++) {
                hex.append(String.format("%02x", digest[i]));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

