package org.springframework.samples.petclinic.mapper;

import java.util.Set;

import org.springframework.samples.petclinic.model.CustomerCode;
import org.springframework.samples.petclinic.model.MembershipLevels;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's segment formatted '<TIER>_<AREA>'. TIER is 'PREMIUM' when the
 * (capped) membershipLevel is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when
 * the locality is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
 */
final class OwnerSegments {

    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");

    private OwnerSegments() {
    }

    /** The '<TIER>_<AREA>' segment for {@code owner}. */
    static String of(Owner owner) {
        int level = MembershipLevels.levelOf(owner);
        Integer cap = owner.getMembershipLevelCap();
        if (cap != null && cap < level) {
            level = cap;
        }
        String tier = level >= 3 ? "PREMIUM" : "STANDARD";
        String region = CustomerCode.region(owner);
        String area = METRO_REGIONS.contains(region) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }
}

package org.springframework.samples.petclinic.model;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Emits the immutable structured {@code OWNER_CREATED} event to the dedicated
 * {@code AUDIT} logger, one per created owner, as a JSON object
 * {@code {seq, ownerId, memberId, membershipLevel, event}}. {@code seq} is a
 * monotonically increasing integer across creates.
 *
 * <p>The event carries the owner's primary identifier — the memberId — via
 * {@link #primaryId(Owner)}.
 */
public final class OwnerCreatedEvent {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final AtomicLong SEQ = new AtomicLong();

    private OwnerCreatedEvent() {
    }

    /** Emit the structured create event for {@code owner}. */
    public static void emit(Owner owner) {
        AUDIT.info(
            "{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
            SEQ.incrementAndGet(), owner.getId(), primaryId(owner), MembershipLevels.levelOf(owner));
    }

    /** The owner's current primary identifier carried by the event. */
    private static String primaryId(Owner owner) {
        return owner.getCustomerCode();
    }
}

